const inputData = {
  name: "Fatima Al-Kaabi",
  phone: "+974 5555 1234",
  email: "fatima.k@example.com",
  budget: 1500000,
  propertyTypes: ["apartment", "villa"],
  contactMethods: ["whatsapp", "email"]
};

const outputItems = [];

inputData.propertyTypes.forEach(property => {
  inputData.contactMethods.forEach(method => {
    outputItems.push({
      json: {
        name: inputData.name,
        phone: inputData.phone,
        email: inputData.email,
        budget: inputData.budget,
        interestedIn: property,
        preferredContact: method
      }
    });
  });
});

return outputItems;
